QUESTION_KINDS = [
    ("identity","evidence","validation"), ("relationship","authority","exception"),
    ("ownership","provenance","access"), ("lifecycle","temporal","retention"),
    ("definition","quality","security"), ("classification","process","interoperability"),
    ("composition","measurement","validation"), ("state","decision","temporal"),
]

def make_finding(raw, index):
    fid, name, description, refs, value_kind, required = raw
    kinds = QUESTION_KINDS[index % len(QUESTION_KINDS)]
    return {
        "id":fid,"name":name,"description":description,"source_refs":refs,
        "questions":[
            {"id":fid+"-q01","text":f"What identifiers, source containers, classes, scope and values define {name.lower()}?","kind":kinds[0],"answer_data":["identifiers and aliases","source and class","scope and values","explicit unknowns"]},
            {"id":fid+"-q02","text":f"Which authority, evidence, method, event time and knowledge time support {name.lower()}?","kind":kinds[1],"answer_data":["authority","evidence and method","event and knowledge time","confidence"]},
            {"id":fid+"-q03","text":f"How may {name.lower()} be validated, disputed, corrected, superseded, retained and disclosed without enabling unsafe exploitation?","kind":kinds[2],"answer_data":["validation","challenge and correction","successor history","retention and access","unsafe-detail boundary"]},
        ],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured source-qualified vulnerability data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing vulnerability record for "+name.lower()+" with source, method, event and knowledge time, confidence and access marking.","media_or_form":["logical vulnerability assertion","authoritative registry, advisory or assessment reference"],"serial":True,"identity_strategy":"Vulnerability record identifier plus "+fid+" assertion or event identifier; description, product, score, date and digest never identify a vulnerability alone.","source_refs":refs}],
        "inline_only_rationale":None,
    }

def structure():
    cursor = 0
    out = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        out_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            made = []
            for raw in findings:
                made.append(make_finding(raw, cursor))
                cursor += 1
            out_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":made})
        out.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":out_layers})
    return {"bundles":out}

